#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int digArtifacts(int n,vector<vector<int>>& artifacts,vector<vector<int>>& dig){unordered_set<long long> seen;
  for(auto&p:dig)seen.insert((long long)p[0]*n+p[1]);int ans=0;
  for(auto&a:artifacts){bool ok=true;for(int r=a[0];r<=a[2];++r)for(int c=a[1];c<=a[3];++c)if(!seen.count((long long)r*n+c))ok=false;ans+=ok;}
  return ans;
 }
};
